def path(p):
    p=pathlib.Path(p)
    return str(p.relative_to(PAPER)).replace('\\','/') if p.is_relative_to(PAPER) else str(p)
def add(loc,quote,pv,ev,files,status='exact_match',details='',fix=None):
    fs=[path(x) for x in files]
    for f in fs: assert f in KEYS, f
    obj={'claim_id':len(claims)+1,'location':loc,'paper_text':quote,'paper_value':pv,'evidence_file':fs,'evidence_value':ev,'status':status,'details':details}
    if fix:obj['recommended_action']=fix
    claims.append(obj)
def prose(loc,quote,ev,files,status='exact_match',details='',fix=None,pv=None):
    assert quote in man, quote
    add('system_paper/manuscript_v1.md: '+loc,quote,quote if pv is None else pv,ev,files,status,details,fix)
def matchnum(token,v):
    if str(token)==str(v):return 'exact_match'
    if v is None: return 'exact_match' if token=='NOT_EVALUATED' else 'number_mismatch'
    try:
        d=decimal.Decimal(token);x=decimal.Decimal(str(v));unit=decimal.Decimal(1).scaleb(d.as_tuple().exponent)
        return 'exact_match' if d==x else ('rounding_ok' if abs(d-x)<=abs(unit)/2+decimal.Decimal('1e-12')*abs(x) else 'number_mismatch')
    except decimal.InvalidOperation:return 'exact_match' if token==str(v) else 'number_mismatch'
def table(name,columns,rows,evidence,details=''):
    f=PAPER/'system_paper/generated_tables'/name
    lines=[x for x in f.read_text(encoding='utf-8-sig').splitlines() if x.startswith('|')]
    header=[v.strip() for v in lines[0].strip('|').split('|')]
    for line in lines[2:]:
        vals=[v.strip() for v in line.strip('|').split('|')]; key=vals[0]
        for i,field in columns.items():
            ev=rows[key][field];status=matchnum(vals[i],ev)
            add(f'system_paper/generated_tables/{name}: {key}, {header[i]}',line,vals[i],ev,evidence(key,field),status,details)
    return lines
