def compact(v,limit=180):
    t=json.dumps(v,ensure_ascii=False) if not isinstance(v,str) else v
    t=t.replace('|','\\|').replace('\n',' ')
    return t if len(t)<=limit else t[:limit-1]+'…'
md += [f'| {c["claim_id"]} | {compact(c["location"],110)} | {compact(c["paper_value"])} | {compact(c["evidence_value"])} | {c["status"]} |' for c in claims]
